package ama.transcript;
import ama.contract.MinutesContracts.*;import ama.contract.TaskContracts.*;import ama.task.*;import ama.task.ExternalOperationPort.*;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;
import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Complete candidate graph persistence, callable only through the genuine registered invocation. */
final class MinutesCandidateWriter {
 private final JdbcTranscriptAuthority authority;private final JdbcTaskPreparations issuer;private final JdbcTemplate j;
 MinutesCandidateWriter(JdbcTranscriptAuthority authority,JdbcTaskPreparations issuer){this.authority=authority;this.issuer=issuer;j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);}
 TypedRef write(TaskDomainPolicy.PreparedDomain held,ExecutionContext context,MinutesExternalPreparation.Observation observation,MinutesGraphCapture.Graph graph){
  return writeGraph(held,context,observation,graph,"PENDING");
 }
 TypedRef writeRetained(JdbcGenerationRetention retention,GenerationRetentionPolicy.Retention capability,MinutesExternalPreparation.Observation observation,MinutesGraphCapture.Graph graph){var invocation=retention.requireInvocation(capability);return writeGraph(invocation.domain(),invocation.context(),observation,graph,"STALE");}
 private TypedRef writeGraph(TaskDomainPolicy.PreparedDomain held,ExecutionContext context,MinutesExternalPreparation.Observation observation,MinutesGraphCapture.Graph graph,String state){
  var facts=issuer.requireExternal(held,context);var plan=observation.plan;require(plan!=null&&facts.spec().equals(plan.spec())&&facts.taskId().equals(observation.request.taskId),PROVENANCE_UNAVAILABLE);
  require(j.queryForList("SELECT id FROM generation_candidate WHERE task_id=? FOR UPDATE",String.class,facts.taskId()).isEmpty(),PROVENANCE_UNAVAILABLE);
  long body=next(graph,"minutes_revision"),set=next(graph,"element_set");var rows=plan.rows(body,set);
  for(var row:rows)insert(row);
  require(j.update("INSERT INTO generation_candidate(id,meeting_id,input_id,task_id,minutes_revision_id,element_set_id,base_revision,input_fingerprint,state,created_at,decided_at) VALUES (?,?,?,?,?,?,?,?,?,?,NULL)",plan.candidateId(),facts.spec().subject().id(),facts.spec().input().id(),facts.taskId(),plan.bodyId(),plan.setId(),facts.spec().businessVersion(),facts.spec().inputFingerprint(),state,java.time.LocalDateTime.ofInstant(java.time.Instant.parse(plan.createdAt()),java.time.ZoneOffset.UTC))==1,PROVENANCE_UNAVAILABLE);
  validateGraph(held,context,observation,new TypedRef("GENERATION_CANDIDATE",plan.candidateId()),state);
  new ama.audit.JdbcAuditAdapter(authority.dataSource()).append(new ama.contract.AuditContracts.AuditEvent(plan.owner(),"MINUTES_GENERATION_COMPLETED",facts.spec().subject().id(),facts.spec().businessVersion(),"SUCCEEDED",facts.executionId(),java.time.Instant.now()));
  return new TypedRef("GENERATION_CANDIDATE",plan.candidateId());
 }
 private static long next(MinutesGraphCapture.Graph graph,String name){var highest=graph.auxiliary().get(name+"_history_max");require(highest!=null&&highest.size()<=1,PROVENANCE_UNAVAILABLE);long old=highest.isEmpty()?0:((Number)highest.getFirst().get("revision")).longValue();require(old>=0&&old<Long.MAX_VALUE-1,BUDGET_EXCEEDED);return old+1;}
 private void insert(FullRow row){var columns=row.table().columns();var args=new Object[columns.size()];for(int i=0;i<args.length;i++){var value=row.cells().get(i);args[i]=value instanceof NullCell?null:value instanceof UIntCell n?n.value():columns.get(i).kind()==CellKind.TIMESTAMP?java.time.LocalDateTime.ofInstant(java.time.Instant.parse(((TextCell)value).value()),java.time.ZoneOffset.UTC):((TextCell)value).value();}require(j.update("INSERT INTO "+row.table().sqlName()+"("+String.join(",",columns.stream().map(ColumnSpec::name).toList())+") VALUES ("+String.join(",",Collections.nCopies(args.length,"?"))+")",args)==1,PROVENANCE_UNAVAILABLE);}
 void validate(TaskDomainPolicy.PreparedDomain held,ExecutionContext context,MinutesExternalPreparation.Observation observation,TypedRef output){validateGraph(held,context,observation,output,"PENDING");}
 void validateStaleReplay(TaskDomainPolicy.PreparedDomain held,ExecutionContext context,MinutesExternalPreparation.Observation observation){require(observation.plan!=null,PROVENANCE_UNAVAILABLE);validateGraph(held,context,observation,new TypedRef("GENERATION_CANDIDATE",observation.plan.candidateId()),"STALE");}
 void validateRetained(JdbcGenerationRetention retention,GenerationRetentionPolicy.Retention capability,MinutesExternalPreparation.Observation observation,TypedRef output){var invocation=retention.requireInvocation(capability);validateGraph(invocation.domain(),invocation.context(),observation,output,"STALE");}
 private void validateGraph(TaskDomainPolicy.PreparedDomain held,ExecutionContext context,MinutesExternalPreparation.Observation observation,TypedRef output,String state){
  var facts=issuer.requireExternal(held,context);var plan=observation.plan;require(plan!=null&&output!=null&&output.kind().equals("GENERATION_CANDIDATE")&&output.id().equals(plan.candidateId()),PROVENANCE_UNAVAILABLE);var budget=observation.request.input.budget();var reader=new SavedTranscriptRows(j,budget,authority.readBudget().maxManifestBytes());
  var candidate=reader.read(MinutesGraphCapture.CANDIDATE,"task_id=?","id",1,false,facts.taskId());require(candidate.size()==1,PROVENANCE_UNAVAILABLE);var c=candidate.getFirst();require(plan.candidateId().equals(c.get("id"))&&facts.spec().subject().id().equals(c.get("meeting_id"))&&facts.spec().input().id().equals(c.get("input_id"))&&plan.bodyId().equals(c.get("minutes_revision_id"))&&plan.setId().equals(c.get("element_set_id"))&&facts.spec().businessVersion()==((Number)c.get("base_revision")).longValue()&&facts.spec().inputFingerprint().equals(c.get("input_fingerprint"))&&state.equals(c.get("state"))&&plan.createdAt().equals(c.get("created_at"))&&c.get("decided_at")==null,PROVENANCE_UNAVAILABLE);
  var body=reader.rows(Table.MINUTES_REVISION,"id=?","id",1,true,plan.bodyId());var set=reader.rows(Table.ELEMENT_SET,"id=?","id",1,true,plan.setId());require(body.size()==1&&set.size()==1,PROVENANCE_UNAVAILABLE);var expected=plan.rows(body.getFirst().number("revision"),set.getFirst().number("revision"));
  for(Table table:List.of(Table.MINUTES_REVISION,Table.ELEMENT_SET,Table.MINUTES_ELEMENT,Table.ACTION_ITEM,Table.ACTION_SUGGESTION,Table.SENSITIVE_DETECTION,Table.BACKGROUND_NOTE,Table.SENSITIVE_DETECTION_SOURCE,Table.BACKGROUND_NOTE_SOURCE,Table.EVIDENCE_LINK)){
   String where;Object[] args;switch(table){case MINUTES_REVISION->{where="id=?";args=new Object[]{plan.bodyId()};}case ELEMENT_SET->{where="id=?";args=new Object[]{plan.setId()};}case MINUTES_ELEMENT,SENSITIVE_DETECTION,BACKGROUND_NOTE->{where="set_id=?";args=new Object[]{plan.setId()};}case ACTION_ITEM,ACTION_SUGGESTION->{where="element_id IN (SELECT id FROM minutes_element WHERE set_id=?)";args=new Object[]{plan.setId()};}case SENSITIVE_DETECTION_SOURCE->{where="detection_id IN (SELECT id FROM sensitive_detection WHERE set_id=?)";args=new Object[]{plan.setId()};}case BACKGROUND_NOTE_SOURCE->{where="note_id IN (SELECT id FROM background_note WHERE set_id=?)";args=new Object[]{plan.setId()};}default->{where="minutes_revision_id=? OR element_id IN (SELECT id FROM minutes_element WHERE set_id=?)";args=new Object[]{plan.bodyId(),plan.setId()};}}
   var wanted=expected.stream().filter(r->r.table()==table).toList();var actual=reader.rows(table,where,String.join(",",table.primaryKey()),Math.max(1,wanted.size()),true,args);require(actual.size()==wanted.size()&&new HashSet<>(actual).equals(new HashSet<>(wanted)),PROVENANCE_UNAVAILABLE);
  }
  var locators=new ArrayList<>(expected.stream().filter(r->r.table()==Table.SOURCE_LOCATOR).toList());locators.addAll(plan.reusedLocators());for(var locator:locators)require(reader.rows(Table.SOURCE_LOCATOR,"id=?","id",1,true,locator.string("id")).equals(List.of(locator)),PROVENANCE_UNAVAILABLE);
  require(j.queryForList("SELECT id FROM result_review WHERE minutes_revision_id=? OR element_id IN (SELECT id FROM minutes_element WHERE set_id=?) ORDER BY id LIMIT 1 FOR UPDATE",plan.bodyId(),plan.setId()).isEmpty(),PROVENANCE_UNAVAILABLE);
 }
}
